// Valida el evento y detecta duplicados. NO marca nada como visto: eso se hace al terminar con
// éxito, para que un evento que falló a medias se reintente (la API lo vuelve a enviar).
const EVENTOS = ['task.created', 'task.updated', 'task.completed', 'task.deleted'];
const cuerpo = $input.first().json.body ?? {};
const vistos = $getWorkflowStaticData('global').vistos ?? {};

const eventId = typeof cuerpo.event_id === 'string' ? cuerpo.event_id : '';
const taskId = Number(cuerpo?.data?.task_id);

let motivo = null;
if (!EVENTOS.includes(cuerpo.event)) motivo = 'evento desconocido';
else if (!/^[0-9a-f-]{36}$/i.test(eventId)) motivo = 'event_id no válido';
else if (!Number.isInteger(taskId) || taskId < 1) motivo = 'task_id no válido';
else if (vistos[eventId]) motivo = 'duplicado';

return [{
  json: {
    procesar: motivo === null,
    motivo,
    event: cuerpo.event,
    event_id: eventId,
    sequence: cuerpo.sequence,
    occurred_at: cuerpo.occurred_at,
    task_id: taskId,
    external_event_id: cuerpo?.data?.external_event_id ?? null,
    changed: cuerpo?.data?.changed ?? [],
  },
}];

// La API respondió: 2xx = tarea leída; 404 = la tarea ya no existe (normal si se borró mientras
// el evento esperaba); cualquier otro código es un fallo y se lanza para que n8n responda con error
// y la API vuelva a enviar el evento más tarde.
const evento = $('Validar y detectar duplicados').first().json;
const respuesta = $input.first().json;
const codigo = respuesta.statusCode;

if (codigo === 404) return [{ json: { tarea: null, nota: 'la tarea ya no existe' } }];
if (codigo >= 200 && codigo < 300) return [{ json: { tarea: respuesta.body } }];
throw new Error('La API respondió ' + codigo + ' al consultar la tarea ' + evento.task_id);

// Marca el evento como procesado (así un reintento posterior se reconoce como duplicado).
// Se guardan los últimos 7 días y como máximo 5000 identificadores, para no crecer sin límite.
const MAX_IDS = 5000;
const SIETE_DIAS = 7 * 24 * 3600 * 1000;
const evento = $('Validar y detectar duplicados').first().json;
const estado = $getWorkflowStaticData('global');
const vistos = estado.vistos ?? {};

const ahora = Date.now();
vistos[evento.event_id] = ahora;
for (const [id, momento] of Object.entries(vistos)) {
  if (ahora - momento > SIETE_DIAS) delete vistos[id];
}
const ids = Object.keys(vistos);
if (ids.length > MAX_IDS) {
  ids.sort((a, b) => vistos[a] - vistos[b]).slice(0, ids.length - MAX_IDS).forEach((id) => delete vistos[id]);
}
estado.vistos = vistos;

return [{
  json: {
    status: 'procesado',
    event: evento.event,
    event_id: evento.event_id,
    sequence: evento.sequence,
    task_id: evento.task_id,
  },
}];
